//! Production constructors only. Library order is generated by the genuine
//! environment KDF; no hand, mana, zone, journal or executable fixture is injected.
use crate::{
    card_def::{self, CARD_DEFS},
    ids::{ObjectId, PlayerId},
    rl::{ActionSemanticV1 as A, TargetRefV1},
    rl_session::{FastActorSessionV1, NextFiveSessionV59},
    rules_meaning_next_five_v59::FamilyV59,
    state::{GameState, Zone},
};
pub(crate) const EPISODE: u64 = 59_452;
pub(crate) const SEED: u64 = 110_452;
pub(crate) const LIMITS: (u64, u64) = (20_000, 20_000);
pub(crate) fn rows(family: FamilyV59) -> Vec<crate::limited_session_v1::CustomCardCountV1> {
    let text = match family {
        FamilyV59::Snack => include_str!(
            "../../../data/limited/fdn_v1/FDN_reference_midnight_snack_full_candidate.dck"
        ),
        FamilyV59::Replication => include_str!(
            "../../../data/limited/fdn_v1/FDN_reference_extravagant_replication_full_candidate.dck"
        ),
        FamilyV59::Infernal => include_str!(
            "../../../data/limited/fdn_v1/FDN_reference_infernal_vessel_full_candidate.dck"
        ),
        FamilyV59::Giada => {
            include_str!("../../../data/limited/fdn_v1/FDN_reference_giada_full_candidate.dck")
        }
        FamilyV59::Goblin => include_str!(
            "../../../data/limited/fdn_v1/FDN_reference_goblin_negotiation_full_candidate.dck"
        ),
    };
    text.lines()
        .map(|line| {
            let (count, name) = line.split_once(' ').unwrap();
            crate::limited_session_v1::CustomCardCountV1 {
                name: name.into(),
                count: count.parse().unwrap(),
            }
        })
        .collect()
}

pub(crate) fn boards(family: FamilyV59) -> [Vec<u16>; 2] {
    let deck = crate::limited_session_v1::CustomDeckV1 {
        cards: rows(family),
    }
    .resolve_next_five_v59()
    .unwrap();
    assert_eq!(deck.len(), 40);
    assert_eq!(
        deck.iter()
            .filter(|&&id| CARD_DEFS[usize::from(id)].name == family.name())
            .count(),
        4
    );
    [deck.clone(), deck]
}
pub(crate) fn identities() -> [String; 2] {
    [
        "production-next-five-left".into(),
        "production-next-five-right".into(),
    ]
}
pub(crate) fn owner(family: FamilyV59, actor: PlayerId) -> NextFiveSessionV59 {
    NextFiveSessionV59::reset(EPISODE, SEED, LIMITS, identities(), boards(family), actor).unwrap()
}
pub(crate) fn native(family: FamilyV59, actor: PlayerId) -> FastActorSessionV1 {
    FastActorSessionV1::reset_next_five_v59(
        EPISODE,
        SEED,
        LIMITS,
        identities(),
        boards(family),
        actor,
    )
    .unwrap()
}
pub(crate) fn tapped(state: &GameState, actor: PlayerId) -> usize {
    state.players[actor.index()]
        .battlefield
        .iter()
        .filter(|id| state.objects.get(**id).tapped)
        .count()
}
pub(crate) fn choose(
    state: &GameState,
    actor: PlayerId,
    family: FamilyV59,
    source: Option<ObjectId>,
    actions: &[A],
) -> usize {
    let find = |f: &dyn Fn(&A) -> bool| actions.iter().position(f);
    if let Some(i) = find(&|a| {
        matches!(
            a,
            A::ChooseLondonMulligan {
                mulligan: false,
                ..
            }
        )
    }) {
        return i;
    }
    if let Some(i) = find(&|a| {
        matches!(
            a,
            A::ChooseEffectOption {
                option_index: 1,
                ..
            }
        )
    }) {
        return i;
    }
    if let Some(i) = find(&|a| {
        matches!(a,A::ChooseTarget{target:TargetRefV1::Object{object},..}
        if object.controller==actor.into() && CARD_DEFS[usize::from(object.card_db_id)].name=="Axgard Cavalry")
    }) {
        return i;
    }
    if let Some(i) = find(&|a| matches!(a,A::PlayLand{actor:p,..}if *p==actor.into())) {
        return i;
    }
    let support = rows(family)[1].name.clone();
    let has_support = state.players[actor.index()]
        .battlefield
        .iter()
        .any(|id| CARD_DEFS[usize::from(state.objects.get(*id).card_def)].name == support);
    if !has_support {
        if let Some(i) = find(&|a| {
            matches!(a,A::CastSpell{actor:p,source,..}if *p==actor.into()
            && CARD_DEFS[usize::from(source.card_db_id)].name==support)
        }) {
            return i;
        }
    } else if source.is_none() {
        if let Some(i) = find(&|a| {
            matches!(a,A::CastSpell{actor:p,source,..}if *p==actor.into()
            && CARD_DEFS[usize::from(source.card_db_id)].name==family.name())
        }) {
            return i;
        }
    }
    if let Some(i) = find(&|a| {
        matches!(
            a,
            A::Pass { .. }
                | A::ChooseAttackerInclusion { include: false, .. }
                | A::ChooseBlockerInclusion { include: false, .. }
        )
    }) {
        return i;
    }
    if let Some(i) = find(&|a| matches!(a,A::DeclareAttackers{attackers,..}if attackers.is_empty()))
    {
        return i;
    }
    if let Some(i) = find(
        &|a| matches!(a,A::Discard{cards,..}if cards.iter().all(|r|CARD_DEFS[usize::from(r.card_db_id)].is_land)),
    ) {
        return i;
    }
    if let Some(i) = find(&|a| matches!(a, A::Discard { .. })) {
        return i;
    }
    panic!("unexpected production NextFive menu: {actions:?}");
}
pub(crate) fn selected_source(action: &A, family: FamilyV59) -> Option<ObjectId> {
    match action {
        A::CastSpell { source, .. }
            if CARD_DEFS[usize::from(source.card_db_id)].name == family.name() =>
        {
            Some(ObjectId(source.arena_id))
        }
        _ => None,
    }
}
pub(crate) fn paid(
    state: &GameState,
    actor: PlayerId,
    family: FamilyV59,
    source: ObjectId,
    before: usize,
) -> bool {
    if state.engine.pending_cast.is_some() {
        return false;
    }
    let Some(row) = state
        .stack
        .iter()
        .find(|r| r.source == source && r.kind == crate::state::StackItemKind::Spell)
    else {
        return false;
    };
    assert_eq!(row.controller, actor);
    assert_eq!(state.objects.get(source).zone, Zone::Stack);
    let definition = &CARD_DEFS[usize::from(state.objects.get(source).card_def)];
    assert_eq!(definition.name, family.name());
    assert_eq!(
        tapped(state, actor) - before,
        usize::from(definition.mana_value) + usize::from(family == FamilyV59::Goblin)
    );
    assert_eq!(state.players[actor.index()].mana_pool, [0; 6]);
    crate::engine::validated_stack_item_target_spec(row, state).unwrap();
    if family == FamilyV59::Goblin {
        assert_eq!(row.targets.len(), 1);
        assert_eq!(row.v4.x_value, 1);
    }
    true
}
pub(crate) fn completed(state: &GameState, family: FamilyV59, source: ObjectId) -> bool {
    let expected = if family == FamilyV59::Goblin {
        Zone::Graveyard
    } else {
        Zone::Battlefield
    };
    state.objects.get(source).zone == expected
        && state.stack.is_empty()
        && state.engine.pending_effect.is_none()
        && state.engine.pending_triggers.is_empty()
        && state.engine.pending_cast.is_none()
        && state.engine.pending_activation.is_none()
}
pub(crate) fn assert_completed(state: &GameState, family: FamilyV59, source: ObjectId) {
    assert!(completed(state, family, source));
    assert_eq!(
        state.objects.get(source).owner,
        state.objects.get(source).controller
    );
    assert!(state.engine.halted.is_none());
    let restored: GameState = serde_json::from_slice(&serde_json::to_vec(state).unwrap()).unwrap();
    assert_eq!(&restored, state);
    assert_eq!(restored.state_hash(), state.state_hash());
    assert_eq!(
        card_def::card_id_by_name(family.name()),
        Some(state.objects.get(source).card_def)
    );
}
#[test]
fn production_five_full_candidate_real_decks_paid_owner_and_serialized_restore_both_seats() {
    for family in FamilyV59::ALL {
        for actor in [PlayerId::P0, PlayerId::P1] {
            let mut owner = owner(family, actor);
            let mut native = native(family, actor);
            let mut foreign = self::owner(family, actor);
            let foreign_before = foreign.fixture_state_v59().clone();
            assert!(foreign.restore_v59(&owner.snapshot_v59()).is_err());
            assert_eq!(foreign.fixture_state_v59(), &foreign_before);
            let mut source = None;
            let mut before = 0;
            let mut saved = None;
            let mut replay_completed = false;
            let mut completed_once = None;
            for _ in 0..4096 {
                assert_eq!(owner.current_response(), native.current_response());
                assert_eq!(owner.fixture_state_v59(), native.next_five_fixture_state());
                assert_eq!(
                    owner.fixture_counts_v59(),
                    (native.policy_step_count(), native.physical_decision_count())
                );
                if let Some(id) = source {
                    if completed(owner.fixture_state_v59(), family, id) {
                        assert_completed(owner.fixture_state_v59(), family, id);
                        let bytes = serde_json::to_vec(owner.fixture_state_v59()).unwrap();
                        if let Some(first) = &completed_once {
                            assert_eq!(&bytes, first);
                            replay_completed = true;
                            break;
                        }
                        completed_once = Some(bytes);
                        let (own, nat) = saved.as_ref().unwrap();
                        let stale = owner.decision_v59().unwrap();
                        owner.restore_v59(own).unwrap();
                        native.restore_v1(nat);
                        let before = owner.fixture_state_v59().clone();
                        assert!(owner.validate_decision_v59(&stale).is_err());
                        assert_eq!(owner.fixture_state_v59(), &before);
                        continue;
                    }
                }
                let d = owner.decision_v59().unwrap();
                let i = choose(
                    owner.fixture_state_v59(),
                    actor,
                    family,
                    source,
                    d.actions(),
                );
                if let Some(id) = selected_source(&d.actions()[i], family) {
                    source = Some(id);
                    before = tapped(owner.fixture_state_v59(), actor);
                }
                let response = owner.step_v59(&d, u32::try_from(i).unwrap()).unwrap();
                assert_eq!(
                    response,
                    native
                        .step(
                            d.expected().episode_id,
                            d.expected().step,
                            u32::try_from(i).unwrap()
                        )
                        .unwrap()
                );
                if saved.is_none()
                    && source.is_some_and(|id| {
                        paid(owner.fixture_state_v59(), actor, family, id, before)
                    })
                {
                    saved = Some((owner.snapshot_v59(), native.snapshot_v1()));
                }
            }
            assert!(replay_completed);
        }
    }
}
